 4	final class ArticulationPointAnalysis implements GraphAnalysis<List<Integer>> {
 5	    @Override
 6	    public void validate(Graph graph) {
 7	        if (!graph.isUndirected()) {
 8	            throw new IllegalArgumentException("Articulation points require an undirected graph");
 9	        }
10	    }
11	
12	    @Override
13	    public List<Integer> compute(Graph graph) {
14	        return new ArticulationPointTraversal(graph).run();
15	    }
16	
17	    private static final class ArticulationPointTraversal extends DepthFirstGraphAnalysis<List<Integer>> {
18	        private static final int NO_ARTICULATION_POINTS = -1;
19	
20	        private final int[] lowLink;
21	        private final boolean[] articulationPoint;
22	
23	        private ArticulationPointTraversal(Graph graph) {
24	            super(graph);
25	            this.lowLink = new int[vertexCount()];
26	            this.articulationPoint = new boolean[vertexCount()];
27	        }
28	
29	        @Override
30	        protected void onDiscoverVertex(int vertex, int parent) {
31	            lowLink[vertex] = discoveryTimeOf(vertex);
32	        }
33	
34	        @Override
35	        protected void afterChildTraversal(int vertex, int child, int parent) {
36	            lowLink[vertex] = Math.min(lowLink[vertex], lowLink[child]);
37	
38	            if (!isRoot(parent) && lowLink[child] >= discoveryTimeOf(vertex)) {
39	                articulationPoint[vertex] = true;
40	            }
41	        }
42	
43	        @Override
44	        protected void onBackEdge(int vertex, int neighbor) {
45	            lowLink[vertex] = Math.min(lowLink[vertex], discoveryTimeOf(neighbor));
46	        }
47	
48	        @Override
49	        protected void onCompleteVertex(int vertex, int parent, int childCount) {
50	            if (isRoot(parent) && childCount > 1) {
51	                articulationPoint[vertex] = true;
52	            }
53	        }
54	
55	        @Override
56	        protected List<Integer> buildResult() {
57	            ArrayList<Integer> result = new ArrayList<>();
58	
59	            for (int vertex = 0; vertex < articulationPoint.length; vertex++) {
60	                if (articulationPoint[vertex]) {
61	                    result.add(vertex);
62	                }
63	            }
64	
65	            if (result.isEmpty()) {
66	                result.add(NO_ARTICULATION_POINTS);
67	            }
68	
69	            return result;
70	        }
71	    }
72	}

